import{_ as s,c as i,o as a,aj as t}from"./chunks/framework.Id7s26SP.js";const k=JSON.parse('{"title":"App Secrets","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/app-secrets.md","filePath":"getting-started/app-secrets.md"}'),n={name:"getting-started/app-secrets.md"};function r(l,e,o,c,h,d){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="app-secrets" tabindex="-1">App Secrets <a class="header-anchor" href="#app-secrets" aria-label="Permalink to “App Secrets”">​</a></h1><p>App secrets store credentials for server-side use. Set a secret with the CLI, then reference it in configuration with <code>{{secrets.KEY}}</code> or read it from a <a href="./server-functions.html">server function</a>. Keep secret values out of your repo and client code.</p><h2 id="managing-secrets" tabindex="-1">Managing Secrets <a class="header-anchor" href="#managing-secrets" aria-label="Permalink to “Managing Secrets”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Create or update a secret</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secrets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OPENAI_API_KEY</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --value</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sk-...</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --summary</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;OpenAI production key&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># List secrets (values are never shown)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secrets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Delete a secret</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secrets</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OPENAI_API_KEY</span></span></code></pre></div><p>Secrets are write-only: once set, a value can be overwritten or deleted but never read back — <code>list</code> shows keys and summaries only. Use <code>--summary</code> so you can tell keys apart later.</p><p>Secrets are scoped to an app, so each of your <a href="./primitive-cli.html#named-environments">environments</a> (dev, staging, production) keeps its own values — set the production key with <code>--env prod</code> and the development key with <code>--env dev</code>.</p><p>An app holds up to <strong>100 secrets</strong>, each value up to 2 KB. Every credential your server side uses — an integration&#39;s API key, a webhook trigger&#39;s signing secret, a token a function reads — is one key, so plan the budget across all of them.</p><h2 id="referencing-secrets" tabindex="-1">Referencing Secrets <a class="header-anchor" href="#referencing-secrets" aria-label="Permalink to “Referencing Secrets”">​</a></h2><p>Server-side config refers to a secret as <code>{{secrets.KEY}}</code>, resolved at the moment the config runs:</p><table tabindex="0"><thead><tr><th>Surface</th><th>Where secrets resolve</th></tr></thead><tbody><tr><td><a href="./api-integrations.html">API Integrations</a></td><td><code>requestConfig.defaultHeaders</code> and <code>requestConfig.staticQuery</code> — resolved into the outbound request</td></tr><tr><td><a href="./server-functions-context.html#reading-secrets-and-config-vars">Server Functions</a></td><td><code>ctx.secret(&quot;KEY&quot;)</code>, for a function that declares <code>secret:KEY</code> in its <code>capabilities</code></td></tr><tr><td><a href="./inbound-webhooks.html#signing-secrets">Inbound webhooks</a></td><td>A webhook trigger&#39;s <code>signingSecret</code> — which must be a whole reference — resolved server-side when an incoming event is verified</td></tr><tr><td><a href="./working-with-databases.html">Databases</a></td><td>Server-stamped field triggers can read <code>secrets.*</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">The CEL <code>secrets.*</code> variable is declared-only</p><p>Unlike the <code>{{secrets.KEY}}</code> template form, which resolves any secret you&#39;ve set, <code>secrets.*</code> in a CEL expression binds only the keys a database or <a href="./collections.html">collection</a> type config declares in a <code>secrets = [&quot;KEY&quot;]</code> list — see <a href="./access-control.html#the-identity-context">Access Control</a> for the rule.</p></div><p>For example, an integration authenticates with a header that names the secret:</p><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># primitive/dev/integrations/openai.toml</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">requestConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">defaultHeaders</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Authorization = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bearer {{secrets.OPENAI_API_KEY}}&quot;</span></span></code></pre></div><h2 id="keep-secrets-server-side" tabindex="-1">Keep Secrets Server-Side <a class="header-anchor" href="#keep-secrets-server-side" aria-label="Permalink to “Keep Secrets Server-Side”">​</a></h2><p>The point of the store is that secret values only ever exist where the server resolves them:</p><ul><li><strong>Never inline credentials in TOML</strong> — config files are committed to your repo. Reference <code>{{secrets.KEY}}</code> instead.</li><li><strong>Keep credentials in integration config, not in function code</strong> — a function&#39;s <a href="./server-functions-context.html#calling-an-outside-service"><code>ctx.integrations.call</code></a> has the credential resolved server-side into the request, so the value never enters the function at all. Reach for <code>ctx.secret</code> only when the function itself must hold the value, and never print it: log records redact a secret&#39;s value on a best-effort basis only.</li><li><strong>Clients can&#39;t read secrets</strong> — there is no client API for secret values; apps only ever see the results of server-side calls that used them.</li></ul><h2 id="config-vars" tabindex="-1">Config Vars <a class="header-anchor" href="#config-vars" aria-label="Permalink to “Config Vars”">​</a></h2><p><strong>Config vars</strong> store non-secret settings, such as a group ID or API hostname. Their values are visible in configuration, logs, and the Admin Console. Use a secret for credentials.</p><p>Vars are configuration, so they are authored in <code>vars.toml</code> and applied with <code>config push</code> (see <a href="#syncing-config-vars">Syncing Config Vars</a> below):</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Create or update a var</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vars</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ADMIN_GROUP_ID=grp_01ABC</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --only</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> var/ADMIN_GROUP_ID</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Read vars back from the server (values are shown — vars are not secret)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vars</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vars</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ADMIN_GROUP_ID</span></span></code></pre></div><p>Delete a var by removing its line from <code>vars.toml</code> and pushing: a key the file no longer declares is deleted server-side on the next push, no <code>--prune</code> needed.</p><p>Unlike secrets, vars are readable: <code>list</code> shows every value, and a var may appear unmasked in debug traces. Never store a credential in a var. Vars (like secrets) can also be managed from the <a href="./admin-console.html">Admin Console</a>, where their values display in plain text.</p><p>Vars share the secrets’ per-app and value-size limits. Push updates a var by key; if the store is full, it reports <code>VAR_LIMIT_REACHED</code>.</p><h2 id="referencing-vars" tabindex="-1">Referencing Vars <a class="header-anchor" href="#referencing-vars" aria-label="Permalink to “Referencing Vars”">​</a></h2><p>Reference vars as <code>{{vars.KEY}}</code> in integration headers or query parameters. Read them in a function with <code>ctx.configVar(&quot;KEY&quot;)</code>. A function caches each var for its current version, so push a new function version after changing a var.</p><div class="tip custom-block"><p class="custom-block-title">Vars are visible where secrets are hidden</p><p>A var resolved into a template is never redacted — logs and request previews show its value, since vars aren&#39;t secret. And a <code>{{vars.KEY}}</code> reference to a var key that doesn&#39;t exist isn&#39;t checked when you save the config; it&#39;s left as a literal unresolved placeholder at call time, unlike a <code>{{secrets.KEY}}</code> reference to a missing secret, which fails the save.</p></div><div class="warning custom-block"><p class="custom-block-title">CEL rules read declared vars only</p><p>Same declared-only rule as secrets: <code>vars.&lt;KEY&gt;</code> binds only the keys the owning config declares in a <code>vars = [&quot;KEY&quot;]</code> list — see <a href="./access-control.html#the-identity-context">Access Control</a>. Unlike an undeclared secret, an unbound var doesn&#39;t quietly deny: the rule errors, so check first when the key may be missing — <code>&#39;KEY&#39; in vars</code> is false rather than failing, and <code>vars.?KEY</code> gives you an optional.</p></div><p>A rule then reads the declared var like any other CEL variable:</p><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">access = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;isMemberOf(&#39;team&#39;, vars.ADMIN_GROUP_ID)&quot;</span></span></code></pre></div><h2 id="syncing-config-vars" tabindex="-1">Syncing Config Vars <a class="header-anchor" href="#syncing-config-vars" aria-label="Permalink to “Syncing Config Vars”">​</a></h2><p>Unlike secrets — which never appear in TOML — config vars are part of the <a href="./configuring-primitive-services.html#the-sync-loop">sync loop</a>: <code>primitive config pull</code> writes every var to a flat <code>vars.toml</code> at the root of the config directory, sibling to <code>app.toml</code>:</p><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Per-environment non-secret config vars.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Bind as {{ vars.KEY }} in integration config and vars.* in CEL rules.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Values are checked into the repo and NOT secret — never put a credential</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># here; use \`primitive secrets\` for that.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ADMIN_GROUP_ID = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;grp_01ABC&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">API_HOST = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://api.example.com&quot;</span></span></code></pre></div><p>Edit <code>vars.toml</code> and push to add or update values. Removing a key deletes the server value without <code>--prune</code>. Concurrent server edits are reported as drift or conflicts. Pull to use the server value; use <code>--force</code> only when you intend to overwrite it. See <a href="./configuring-primitive-services.html#deletions-and-cleared-fields">sync conflict handling</a>.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><ul><li><strong><a href="./api-integrations.html">API Integrations</a></strong> — The most common secret and var consumer: authenticated calls to external APIs</li><li><strong><a href="./server-functions.html">Server Functions</a></strong> — Read secrets and vars from function code</li><li><strong><a href="./configuring-primitive-services.html">Configuring Primitive Services</a></strong> — The sync loop your secret- and var-referencing config travels through</li></ul>`,35)])])}const g=s(n,[["render",r]]);export{k as __pageData,g as default};
